import { Link } from "react-router";
import logoEmblem from "~/assets/logo/logo-emblem.png";
import logoStacked from "~/assets/logo/logo-stacked.png";

interface LogoProps {
  className?: string;
  /** "horizontal": header logo. "stacked": the full logo image as supplied (footer). */
  variant?: "horizontal" | "stacked";
  /** Rendered height in px (stacked variant only). */
  height?: number;
}

// Pixel sizes of the PNGs generated by scripts/process-logo.py.
const EMBLEM = { width: 590, height: 412 };
const STACKED = { width: 590, height: 561 };

/**
 * Header logo, recreated from the client's horizontal logo: the emblem image
 * beside "EntoMetrics Africa" and the tagline set as live text in the logo's
 * own colours, so the lettering stays sharp and legible at nav-bar size.
 */
function HorizontalLogo() {
  return (
    <span className="flex items-center gap-2 sm:gap-2.5">
      <img
        src={logoEmblem}
        alt=""
        width={EMBLEM.width}
        height={EMBLEM.height}
        className="h-[38px] w-auto shrink-0 sm:h-[44px] lg:h-[50px]"
        decoding="async"
      />
      <span className="flex flex-col">
        <span className="flex items-end gap-1">
          <span className="text-[0.875rem] font-bold leading-none tracking-[-0.015em] text-logo-ink sm:text-[0.9375rem] lg:text-[1.0625rem]">
            EntoMetrics Africa
          </span>
          <span aria-hidden className="mb-[0.15em] h-[1.5px] w-3 bg-logo-dash sm:w-3.5" />
        </span>
        <span aria-hidden className="mt-1 h-px w-full bg-rule sm:mt-1.5" />{" "}
        <span className="mt-0.5 text-[0.625rem] font-semibold leading-tight tracking-[0.01em] text-logo-gold sm:mt-1 sm:text-[0.6875rem]">
          Precision Insect Welfare Telemetry
        </span>
      </span>
    </span>
  );
}

export function Logo({ className, height = 120, variant = "horizontal" }: LogoProps) {
  return (
    <Link to="/" className={className}>
      {variant === "horizontal" ? (
        <HorizontalLogo />
      ) : (
        <img
          src={logoStacked}
          alt="EntoMetrics Africa"
          width={Math.round((height * STACKED.width) / STACKED.height)}
          height={height}
          style={{ height, width: "auto" }}
          loading="lazy"
          decoding="async"
        />
      )}
      <span className="sr-only">, home</span>
    </Link>
  );
}
